() => {
  const hero = document.querySelector('main > *:nth-child(1)') ;
  // Find hero container - it's the section right after banner
  const body = document.body;
  // Identify the hero section (contains 'Generate CSS as you code')
  const heading = Array.from(document.querySelectorAll('h1')).find(h => h.textContent.includes('Generate CSS'));
  let el = heading;
  while (el && el.parentElement && !(el.parentElement === document.body || el.parentElement.tagName === 'MAIN')) {
    el = el.parentElement;
  }
  return {
    heroOuterHTML: el ? el.outerHTML.slice(0, 600) : 'not found',
    heroParentTag: el ? el.parentElement.tagName : null,
    heroClass: el ? el.className : null,
    nextSiblingClass: el && el.nextElementSibling ? el.nextElementSibling.className : null,
  };
}

