() => {
  const heading = Array.from(document.querySelectorAll('h1')).find(h => h.textContent.includes('Generate CSS'));
  let hero = heading;
  while (hero && hero.parentElement !== document.body) hero = hero.parentElement;

  const testimonials = [
    {
      quote: "BaroCSS let us drop our build pipeline entirely. Iterating on UI now feels instant.",
      name: "Ava Thompson",
      role: "Frontend Lead, Northwind",
      initials: "AT",
    },
    {
      quote: "The CSS output stays tiny even as our design system grows. Exactly what we hoped for.",
      name: "Marco Ruiz",
      role: "Product Designer, Lumen",
      initials: "MR",
    },
    {
      quote: "Zero config, works in our SSR and client apps alike. The DX is genuinely delightful.",
      name: "Priya Nair",
      role: "Full-stack Engineer, Cobalt",
      initials: "PN",
    },
  ];

  const cardsHTML = testimonials.map(t => `
        <figure class="flex flex-col h-full rounded-2xl border border-slate-200 bg-white p-8 shadow-sm hover:shadow-md transition duration-300">
          <svg class="w-8 h-8 text-blue-500/40 mb-4" viewBox="0 0 24 24" fill="currentColor" aria-hidden="true">
            <path d="M9.5 8C6.46 8 4 10.46 4 13.5V20h6v-6H7c0-1.66 1.34-3 3-3V8zm10 0c-3.04 0-5.5 2.46-5.5 5.5V20h6v-6h-3c0-1.66 1.34-3 3-3V8z"/>
          </svg>
          <blockquote class="flex-1 text-slate-700 text-lg leading-relaxed">${t.quote}</blockquote>
          <figcaption class="mt-6 flex items-center gap-4">
            <span class="flex items-center justify-center w-12 h-12 rounded-full bg-gradient-to-br from-blue-500 to-indigo-500 text-white font-semibold text-sm shrink-0" aria-hidden="true">${t.initials}</span>
            <span class="flex flex-col">
              <span class="font-semibold text-slate-900">${t.name}</span>
              <span class="text-sm text-slate-500">${t.role}</span>
            </span>
          </figcaption>
        </figure>`).join('');

  const section = document.createElement('section');
  section.id = 'testimonials';
  section.className = 'py-16 sm:py-20 border-t border-slate-200';
  section.innerHTML = `
      <div class="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
        <div class="max-w-2xl mx-auto text-center mb-12">
          <span class="inline-flex items-center rounded-full bg-blue-50 text-blue-700 text-xs font-medium px-3 py-1">Testimonials</span>
          <h2 class="mt-4 text-3xl sm:text-4xl font-bold tracking-tight text-slate-900">Loved by product teams</h2>
          <p class="mt-3 text-slate-600">Teams ship faster when styling happens at runtime. Here's what they say.</p>
        </div>
        <div class="grid grid-cols-1 lg:grid-cols-3 gap-6">${cardsHTML}
        </div>
      </div>`;

  hero.insertAdjacentElement('afterend', section);
  return { inserted: true, heroTag: hero.tagName, sectionInDom: !!document.getElementById('testimonials') };
}

